import Foundation

/// User-visible strings (FE-204), keyed by English text so a key with no translation shows English.
/// Base table: `Resources/en.lproj/Localizable.strings`, regenerated by `scripts/extract-strings.sh`.
/// A language is a `Resources/<language>.lproj`; `Bundle` picks it from the user's preferred languages.
public enum L10n {
    /// Bundle holding `Localizable.strings` (the app bundle).
    public static var bundle: Bundle = .main

    /// The language the interface is actually showing, which decides its direction.
    public static var language: String { bundle.preferredLocalizations.first ?? StringTableCheck.baseLanguage }

    /// Fixed for the run: the app shows one language from launch to quit.
    public static let isRightToLeft = Locale.Language(identifier: language).characterDirection == .rightToLeft

    public static func tr(_ key: String) -> String { tr(key, in: bundle) }

    static func tr(_ key: String, in bundle: Bundle) -> String {
        guard !key.isEmpty else { return key }
        return bundle.localizedString(forKey: key, value: key, table: nil)
    }

    private static let missing = "\u{1}missing"

    /// Whether the string table has an entry for `key` (scripted checks and the string-table test).
    public static func hasEntry(_ key: String) -> Bool {
        bundle.localizedString(forKey: key, value: missing, table: nil) != missing
    }

    /// A localized format string filled with arguments (`%@`, `%d`, `%1$@`…). Text arguments are direction-isolated,
    /// so this result is for showing only: text that becomes a file name comes from `plainFormat`.
    public static func format(_ key: String, _ arguments: CVarArg...) -> String {
        String(format: template(key), locale: Locale.current, arguments: arguments.map(isolated))
    }

    /// As `format`, for text that becomes a file name. No locale: localized formatting adds its own direction marks.
    public static func plainFormat(_ key: String, _ arguments: CVarArg...) -> String {
        String(format: template(key), arguments: arguments)
    }

    /// The translated format string. A table with the wrong specifiers can't get past the build,
    /// but one edited afterwards must still never reach `String(format:)`, so it falls back to English.
    public static func template(_ key: String) -> String { template(key, in: bundle) }

    static func template(_ key: String, in bundle: Bundle) -> String {
        let translated = tr(key, in: bundle)
        return translated == key || FormatSpecifiers.compatible(english: key, translation: translated) ? translated : key
    }

    private static func isolated(_ argument: CVarArg) -> CVarArg {
        guard let text = argument as? String else { return argument }
        return BidiText.isolated(text)
    }
}
